.report-document-header { margin: 0 0 10pt !important; padding: 0 !important; border: 0 !important; background: #fff !important; color: #000 !important; break-inside: avoid; }
.report-document-header .report-document-title { margin: 0 0 18pt !important; color: #000 !important; font: bold 10pt/1.2 Arial, sans-serif !important; text-align: center !important; letter-spacing: normal !important; }
.report-document-header .report-document-fields, .report-document-header .report-document-field, .report-document-header span { border: 0 !important; padding: 0 !important; background: #fff !important; color: #000 !important; font: 8pt/1.5 Arial, sans-serif !important; text-align: left !important; }
.report-document-header .report-document-fields, .report-document-header .report-document-field { margin: 0 !important; }
.report-document-header .report-document-label { display: inline-block; width: 145pt; white-space: nowrap; }
.report-document-header .report-document-date { float: right; white-space: nowrap; }
.report-document-context { margin: 2pt 0 5pt; color: #000; font: 7pt Arial, sans-serif; }
.report-document-header--print { display: none !important; }
@media print {
    .report-document-header--print { display: block !important; }
    .population-report > .population-report-header { display: none !important; }
}
